template <> struct Fields<::sc_old_destruction::sc::Destruction::Stats> { static auto of(::sc_old_destruction::sc::Destruction::Stats& x) { return std::tie(x.pieces, x.torn, x.hits, x.collapsed); } static auto of(const ::sc_old_destruction::sc::Destruction::Stats& x) { return std::tie(x.pieces, x.torn, x.hits, x.collapsed); } };
template <> struct Fields<::sc_old_destruction::sc::Destruction::Broken> { static auto of(::sc_old_destruction::sc::Destruction::Broken& x) { return std::tie(x.rings, x.c, x.lo, x.hi, x.new_top, x.top, x.intensity); } static auto of(const ::sc_old_destruction::sc::Destruction::Broken& x) { return std::tie(x.rings, x.c, x.lo, x.hi, x.new_top, x.top, x.intensity); } };
template <> struct Fields<::sc_old_destruction::sc::Destruction::Piece> { static auto of(::sc_old_destruction::sc::Destruction::Piece& x) { return std::tie(x.p, x.v, x.size, x.axis, x.tint, x.yaw, x.angle, x.spin, x.age, x.rest); } static auto of(const ::sc_old_destruction::sc::Destruction::Piece& x) { return std::tie(x.p, x.v, x.size, x.axis, x.tint, x.yaw, x.angle, x.spin, x.age, x.rest); } };
template <> struct Fields<::sc_old_destruction::sc::Destruction::Torn> { static auto of(::sc_old_destruction::sc::Destruction::Torn& x) { return std::tie(x.mesh, x.b, x.center, x.dir, x.axis, x.pivot, x.offset, x.tilt, x.speed, x.lift, x.break_at, x.age); } static auto of(const ::sc_old_destruction::sc::Destruction::Torn& x) { return std::tie(x.mesh, x.b, x.center, x.dir, x.axis, x.pivot, x.offset, x.tilt, x.speed, x.lift, x.break_at, x.age); } };
