    ::sc::lowered::Tally tally("Destruction::points_list(std::vector<std::pair<u32, f32>> &)");
    ::sc::converted::Draw draw;
    for (int call = 0; tally.more(call); ++call) {
      ::sc_old_destruction::sc::Destruction o_self{};
      if (draw.flag()) ::sc::lowered::draw(draw, o_self);
      ::sc_new_destruction::sc::Destruction n_self{};
      ::sc::lowered::carry(o_self, n_self);
      ::sc::lowered::Arg<std::vector<std::pair<u32, f32>> &> o0;
      ::sc::lowered::draw(draw, o0);
      ::sc::lowered::Arg<std::vector<std::pair<u32, f32>> &> n0;
      ::sc::lowered::carry(o0, n0);
      long old_asks = 0, new_asks = 0;
      const bool old_defined = ::sc::lowered::run([&] { o_self.points_list(o0.get()); }, old_asks);
      const bool new_defined = ::sc::lowered::run([&] { n_self.points_list(n0.get()); }, new_asks);
      ::sc::lowered::Differs differs;
      differs.check("its object", o_self, n_self);
      differs.check("its parameter out", o0, n0);
      tally.take(old_defined && new_defined, differs.text, old_asks, new_asks, call);
    }
